import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { orderService } from '../../services/orderService';
import './MyOrders.css';

const fmt = (value) =>
  Number(value || 0).toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 });

const MyOrders = () => {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  const [showReturnModal, setShowReturnModal] = useState(false);
  const [showStatusModal, setShowStatusModal] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [returnReason, setReturnReason] = useState('Size/Fit Issue');
  const [returnComments, setReturnComments] = useState('');
  const [refundMethod, setRefundMethod] = useState('original');
  const [upiId, setUpiId] = useState('');
  const [returnsMap, setReturnsMap] = useState({});

  useEffect(() => {
    orderService.getMyOrders().then(data => {
      const ords = data || [];
      setOrders(ords);

      const loadedReturns = {};
      ords.forEach(order => {
        const saved = localStorage.getItem('return_' + order._id);
        if (saved) {
          loadedReturns[order._id] = JSON.parse(saved);
        }
      });
      setReturnsMap(loadedReturns);
    }).finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="my-orders-page container">
        <h1>My Orders</h1>
        <p>Loading orders...</p>
      </div>
    );
  }

  const handleRequestReturnSubmit = (e) => {
    e.preventDefault();
    if (!selectedOrder) return;
    const returnData = {
      orderId: selectedOrder._id,
      orderNumber: selectedOrder.orderNumber,
      reason: returnReason,
      comments: returnComments,
      refundMethod,
      upiId: refundMethod === 'upi' ? upiId : '',
      status: 'pending', // Starts as pending
      amount: selectedOrder.total,
      requestedAt: new Date().toISOString()
    };
    localStorage.setItem('return_' + selectedOrder._id, JSON.stringify(returnData));
    setReturnsMap(prev => ({ ...prev, [selectedOrder._id]: returnData }));

    window.dispatchEvent(new CustomEvent('add_notification', {
      detail: {
        text: `Return request submitted for Order #${selectedOrder.orderNumber}. Status: UNDER REVIEW.`
      }
    }));

    setShowReturnModal(false);
    setReturnComments('');
    setUpiId('');
  };

  const updateReturnStatus = (orderId, newStatus) => {
    const current = returnsMap[orderId];
    if (!current) return;
    const updated = { ...current, status: newStatus };
    localStorage.setItem('return_' + orderId, JSON.stringify(updated));
    setReturnsMap(prev => ({ ...prev, [orderId]: updated }));

    let statusLabel = 'PENDING';
    if (newStatus === 'approved') statusLabel = 'APPROVED';
    else if (newStatus === 'picked_up') statusLabel = 'PICKED UP';
    else if (newStatus === 'completed') statusLabel = 'REFUND PROCESSED';

    window.dispatchEvent(new CustomEvent('add_notification', {
      detail: {
        text: `Your return request status for Order #${current.orderNumber} is now: ${statusLabel}.`
      }
    }));
  };

  return (
    <div className="my-orders-page container">
      <h1>My Orders</h1>

      {orders.length === 0 ? (
        <div className="empty-state">
          <h3>No orders found</h3>
          <p>You haven't placed any orders yet</p>
          <Link to="/products" className="btn btn-primary">Start Shopping</Link>
        </div>
      ) : (
        <div className="orders-list">
          {orders.map(order => (
            <div className="order-card" key={order._id}>
              <div className="order-header">
                <div>
                  <span className="order-id">Order #{order.orderNumber}</span>
                  <span className="order-date">Placed on {new Date(order.createdAt).toLocaleDateString()}</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  {returnsMap[order._id] && (
                    <span style={{ 
                      background: returnsMap[order._id].status === 'completed' ? '#e6f4ea' : '#fce8e6', 
                      color: returnsMap[order._id].status === 'completed' ? '#137333' : '#c5221f', 
                      fontSize: '0.75rem', 
                      fontWeight: 600, 
                      padding: '4px 8px', 
                      borderRadius: 12 
                    }}>
                      Return: {returnsMap[order._id].status === 'pending' ? 'PENDING' : returnsMap[order._id].status === 'approved' ? 'APPROVED' : returnsMap[order._id].status === 'picked_up' ? 'PICKED UP' : 'COMPLETED'}
                    </span>
                  )}
                  <span className={`order-status ${order.status.toLowerCase()}`}>{order.status}</span>
                </div>
              </div>
              <div className="order-items">
                {(order.vendorOrders ? order.vendorOrders.flatMap(v => v.items || []) : (order.products || [])).map((p, idx) => (
                  <div className="order-item" key={`${order._id}-${idx}`}>
                    <img src={p.image || (p.images && p.images[0]?.url)} alt={p.name} />
                    <div className="order-item-info">
                      <Link to={`/products/${p.product || p._id}`}>{p.name}</Link>
                      <span>{fmt(p.price)}</span>
                    </div>
                  </div>
                ))}
              </div>
              <div className="order-footer">
                <span>Total: {fmt(order.total)}</span>
                <div className="order-actions">
                  {order.status.toLowerCase() === 'delivered' && (
                    returnsMap[order._id] ? (
                      <button 
                        onClick={() => { setSelectedOrder(order); setShowStatusModal(true); }}
                        className="btn btn-outline btn-sm"
                        style={{ color: '#137333', borderColor: '#137333', fontWeight: 600 }}
                      >
                        View Return Status
                      </button>
                    ) : (
                      <button 
                        onClick={() => { setSelectedOrder(order); setShowReturnModal(true); }}
                        className="btn btn-outline btn-sm"
                        style={{ color: '#c5221f', borderColor: '#c5221f', fontWeight: 600 }}
                      >
                        Request Return
                      </button>
                    )
                  )}
                  <Link to={`/track/${order._id || order.orderId}`} className="btn btn-outline btn-sm">Track Order</Link>
                  <Link to="/products" className="btn btn-outline btn-sm">Buy Again</Link>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* REQUEST RETURN FORM MODAL */}
      {showReturnModal && selectedOrder && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)', zIndex: 1000,
          display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20
        }}>
          <div style={{
            background: '#fff', width: '100%', maxWidth: 500, borderRadius: 10,
            boxShadow: '0 8px 24px rgba(0,0,0,0.18)', overflow: 'hidden',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
          }}>
            <div style={{ background: '#c5221f', padding: '15px 20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h3 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 600 }}>Request Return & Refund</h3>
              <button onClick={() => setShowReturnModal(false)} style={{ background: 'none', border: 'none', color: '#fff', fontSize: '1.4rem', cursor: 'pointer' }}>&times;</button>
            </div>
            <form onSubmit={handleRequestReturnSubmit} style={{ padding: 20 }}>
              <p style={{ margin: '0 0 15px 0', fontSize: '0.9rem', color: '#666' }}>
                Order Number: <strong>#{selectedOrder.orderNumber}</strong> • Total amount: <strong>{fmt(selectedOrder.total)}</strong>
              </p>

              <div style={{ marginBottom: 15 }}>
                <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, color: '#333', marginBottom: 5 }}>Reason for Return</label>
                <select 
                  value={returnReason} 
                  onChange={(e) => setReturnReason(e.target.value)}
                  style={{ width: '100%', padding: '8px 10px', border: '1px solid #ccc', borderRadius: 4, fontSize: '0.9rem' }}
                >
                  <option>Defective/Damaged Item</option>
                  <option>Wrong Product Delivered</option>
                  <option>Size/Fit Issue</option>
                  <option>Quality Not as Expected</option>
                  <option>Other</option>
                </select>
              </div>

              <div style={{ marginBottom: 15 }}>
                <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, color: '#333', marginBottom: 5 }}>Explain why you want to return this</label>
                <textarea 
                  rows="3" 
                  value={returnComments} 
                  onChange={(e) => setReturnComments(e.target.value)}
                  placeholder="Tell us what went wrong..." 
                  required
                  style={{ width: '100%', padding: '8px 10px', border: '1px solid #ccc', borderRadius: 4, fontSize: '0.9rem', resize: 'vertical' }}
                />
              </div>

              <div style={{ marginBottom: 20 }}>
                <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, color: '#333', marginBottom: 5 }}>Refund Method</label>
                <div style={{ display: 'flex', gap: 15, marginTop: 5 }}>
                  <label style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '0.9rem', cursor: 'pointer' }}>
                    <input type="radio" name="refund" value="original" checked={refundMethod === 'original'} onChange={() => setRefundMethod('original')} />
                    <span>Original Payment Mode</span>
                  </label>
                  <label style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '0.9rem', cursor: 'pointer' }}>
                    <input type="radio" name="refund" value="upi" checked={refundMethod === 'upi'} onChange={() => setRefundMethod('upi')} />
                    <span>UPI Refund</span>
                  </label>
                </div>
              </div>

              {refundMethod === 'upi' && (
                <div style={{ marginBottom: 20 }}>
                  <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, color: '#333', marginBottom: 5 }}>UPI ID for refund</label>
                  <input 
                    type="text" 
                    value={upiId} 
                    onChange={(e) => setUpiId(e.target.value)} 
                    placeholder="e.g. user@okaxis" 
                    required 
                    style={{ width: '100%', padding: '8px 10px', border: '1px solid #ccc', borderRadius: 4, fontSize: '0.9rem' }}
                  />
                </div>
              )}

              <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', borderTop: '1px solid #eee', paddingTop: 15 }}>
                <button type="button" onClick={() => setShowReturnModal(false)} className="btn btn-outline" style={{ padding: '8px 15px', minWidth: 'auto' }}>Cancel</button>
                <button type="submit" className="btn btn-primary" style={{ padding: '8px 15px', minWidth: 'auto', background: '#c5221f', border: 'none' }}>Submit Return Request</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* VIEW RETURN STATUS & STEPPER MODAL */}
      {showStatusModal && selectedOrder && returnsMap[selectedOrder._id] && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)', zIndex: 1000,
          display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20
        }}>
          <div style={{
            background: '#fff', width: '100%', maxWidth: 550, borderRadius: 10,
            boxShadow: '0 8px 24px rgba(0,0,0,0.18)', overflow: 'hidden',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
          }}>
            {/* Header */}
            <div style={{ background: '#137333', padding: '15px 20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h3 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 600 }}>Return Tracking</h3>
                <span style={{ fontSize: '0.75rem', color: '#a8e6cf' }}>Order #{selectedOrder.orderNumber}</span>
              </div>
              <button onClick={() => setShowStatusModal(false)} style={{ background: 'none', border: 'none', color: '#fff', fontSize: '1.4rem', cursor: 'pointer' }}>&times;</button>
            </div>

            {/* Simulation Panel */}
            <div style={{ background: '#f5f5f5', padding: '15px 20px', borderBottom: '1px solid #eee' }}>
              <span style={{ display: 'block', fontSize: '0.8rem', color: '#666', fontWeight: 600, marginBottom: 8, letterSpacing: '0.5px' }}>
                🚀 DEMO SIMULATOR PANEL (Simulate Admin Approval/Process Flow)
              </span>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                <button 
                  onClick={() => updateReturnStatus(selectedOrder._id, 'pending')}
                  style={{ padding: '6px 12px', borderRadius: 4, border: '1px solid #bbb', background: returnsMap[selectedOrder._id].status === 'pending' ? '#e5e5e5' : '#fff', fontSize: '0.8rem', fontWeight: 600, cursor: 'pointer' }}
                >
                  Set Pending
                </button>
                <button 
                  onClick={() => updateReturnStatus(selectedOrder._id, 'approved')}
                  style={{ padding: '6px 12px', borderRadius: 4, border: 'none', background: returnsMap[selectedOrder._id].status === 'approved' ? '#137333' : '#1b5e20', color: '#fff', fontSize: '0.8rem', fontWeight: 600, cursor: 'pointer' }}
                >
                  Approve Request
                </button>
                <button 
                  onClick={() => updateReturnStatus(selectedOrder._id, 'picked_up')}
                  style={{ padding: '6px 12px', borderRadius: 4, border: 'none', background: returnsMap[selectedOrder._id].status === 'picked_up' ? '#e65100' : '#f57c00', color: '#fff', fontSize: '0.8rem', fontWeight: 600, cursor: 'pointer' }}
                >
                  Mark Picked Up
                </button>
                <button 
                  onClick={() => updateReturnStatus(selectedOrder._id, 'completed')}
                  style={{ padding: '6px 12px', borderRadius: 4, border: 'none', background: returnsMap[selectedOrder._id].status === 'completed' ? '#0d47a1' : '#1976d2', color: '#fff', fontSize: '0.8rem', fontWeight: 600, cursor: 'pointer' }}
                >
                  Finalize Refund
                </button>
              </div>
            </div>

            {/* Stepper Body */}
            <div style={{ padding: '24px 30px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 24, position: 'relative' }}>
                {/* Connector line */}
                <div style={{
                  position: 'absolute', left: 15, top: 15, bottom: 15, width: 2,
                  background: '#e0e0e0', zIndex: 1
                }} />

                {/* Step 1: Requested */}
                <div style={{ display: 'flex', gap: 15, position: 'relative', zIndex: 2 }}>
                  <div style={{
                    width: 32, height: 32, borderRadius: '50%',
                    background: '#137333', color: '#fff',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: '0.9rem'
                  }}>✓</div>
                  <div>
                    <h4 style={{ margin: '0 0 4px 0', fontSize: '0.95rem', fontWeight: 600, color: '#333' }}>Return Requested</h4>
                    <p style={{ margin: 0, fontSize: '0.8rem', color: '#666' }}>Reason: "{returnsMap[selectedOrder._id].reason}"</p>
                    <p style={{ margin: '2px 0 0 0', fontSize: '0.75rem', color: '#999' }}>Requested on {new Date(returnsMap[selectedOrder._id].requestedAt).toLocaleString()}</p>
                  </div>
                </div>

                {/* Step 2: Approved */}
                <div style={{ display: 'flex', gap: 15, position: 'relative', zIndex: 2 }}>
                  <div style={{
                    width: 32, height: 32, borderRadius: '50%',
                    background: ['approved', 'picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '#137333' : '#e0e0e0',
                    color: ['approved', 'picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '#fff' : '#888',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: '0.9rem'
                  }}>
                    {['approved', 'picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '✓' : '2'}
                  </div>
                  <div>
                    <h4 style={{ margin: '0 0 4px 0', fontSize: '0.95rem', fontWeight: 600, color: ['approved', 'picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '#333' : '#888' }}>
                      Request Approved
                    </h4>
                    <p style={{ margin: 0, fontSize: '0.8rem', color: '#666' }}>
                      {['approved', 'picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) 
                        ? 'Your request has been approved. Pick-up is being arranged!' 
                        : 'Awaiting admin review.'}
                    </p>
                  </div>
                </div>

                {/* Step 3: Picked Up */}
                <div style={{ display: 'flex', gap: 15, position: 'relative', zIndex: 2 }}>
                  <div style={{
                    width: 32, height: 32, borderRadius: '50%',
                    background: ['picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '#137333' : '#e0e0e0',
                    color: ['picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '#fff' : '#888',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: '0.9rem'
                  }}>
                    {['picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '✓' : '3'}
                  </div>
                  <div>
                    <h4 style={{ margin: '0 0 4px 0', fontSize: '0.95rem', fontWeight: 600, color: ['picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) ? '#333' : '#888' }}>
                      Item Picked Up
                    </h4>
                    <p style={{ margin: 0, fontSize: '0.8rem', color: '#666' }}>
                      {['picked_up', 'completed'].includes(returnsMap[selectedOrder._id].status) 
                        ? 'Our agent has successfully picked up the item from your address.' 
                        : 'Awaiting courier pick-up.'}
                    </p>
                  </div>
                </div>

                {/* Step 4: Refund Processed */}
                <div style={{ display: 'flex', gap: 15, position: 'relative', zIndex: 2 }}>
                  <div style={{
                    width: 32, height: 32, borderRadius: '50%',
                    background: returnsMap[selectedOrder._id].status === 'completed' ? '#137333' : '#e0e0e0',
                    color: returnsMap[selectedOrder._id].status === 'completed' ? '#fff' : '#888',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: '0.9rem'
                  }}>
                    {returnsMap[selectedOrder._id].status === 'completed' ? '✓' : '4'}
                  </div>
                  <div>
                    <h4 style={{ margin: '0 0 4px 0', fontSize: '0.95rem', fontWeight: 600, color: returnsMap[selectedOrder._id].status === 'completed' ? '#137333' : '#888' }}>
                      Refund Processed
                    </h4>
                    <p style={{ margin: 0, fontSize: '0.8rem', color: '#666' }}>
                      {returnsMap[selectedOrder._id].status === 'completed' 
                        ? `Refund of ${fmt(returnsMap[selectedOrder._id].amount)} credited successfully via ${returnsMap[selectedOrder._id].refundMethod === 'upi' ? 'UPI ID: ' + returnsMap[selectedOrder._id].upiId : 'Original Payment Mode'}.` 
                        : `Refund will be initiated once the item passes quality checks.`}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div style={{ background: '#f5f5f5', padding: '12px 20px', display: 'flex', justifyContent: 'flex-end', borderTop: '1px solid #eee' }}>
              <button onClick={() => setShowStatusModal(false)} className="btn btn-primary" style={{ padding: '8px 18px', minWidth: 'auto', background: '#137333', border: 'none' }}>
                Close Tracker
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MyOrders;
